<?php require_once "../config/auth.php";requireAdmin();require_once "../config/database.php";$q=$conn->query("SELECT e.*,c.club_name,(SELECT COUNT(*) FROM event_registrations r WHERE r.event_id=e.event_id) registered FROM events e JOIN clubs c ON c.club_id=e.club_id ORDER BY e.event_date DESC");?>
